@media(prefers-reduced-motion:reduce){.footer-profile,.footer-profile div,.footer-profile img{opacity:1!important;transform:none!important;transition:none!important;filter:none!important}}

</style>

</head>
<body>
<div id="globalLoader" class="global-loader"><div class="loader-card"><img src="assets/Ciputra.png" alt="Ciputra"><b>Memproses data…</b><span>Mohon tunggu sebentar…</span></div></div>
<div id="public" class="public-shell">
  <div id="publicHome" class="public-home">
    <nav class="public-navbar">
      <a class="public-brand" href="#beranda" onclick="scrollPublic('#beranda');return false"><img src="assets/Ciputra.png" alt="Ciputra"><div><small>Sistem Pengaduan Online</small><b>Ciputra SH-1</b></div></a>
      <div class="public-links">
        <a href="#beranda" onclick="scrollPublic('#beranda');return false">Beranda</a>
        <a href="#layanan" onclick="scrollPublic('#layanan');return false">Layanan</a>
        <a href="#alur" onclick="scrollPublic('#alur');return false">Alur Kerja</a>
        <a href="#" onclick="showPublicComplaint();return false">Pengajuan User</a>
      </div>
      <div class="public-actions">
        <button class="nav-login-btn" onclick="openModal('loginModal')">Login</button>
        <button class="nav-submit-btn" onclick="showPublicComplaint()">Ajukan Pengaduan</button>
      </div>
    </nav>

    <section class="landing-hero" id="beranda">
      <div class="hero-main">
        <div class="hero-badge"><i></i> Garansi perbaikan 3 bulan setelah serah terima</div>
        <h1>Pengaduan rumah lebih <span>cepat, rapi, dan terpantau.</span></h1>
        <p class="hero-desc">Proyek Ciputra SH-1 dibuat untuk menjawab kebutuhan pengelolaan pengaduan dan temuan perbaikan rumah secara lebih terarah. Pemilik rumah dapat mengajukan kendala melalui halaman pengajuan yang jelas, sedangkan Admin SH-1, QC, dan Kontraktor dapat memantau temuan, memberikan jawaban, mengunggah foto dokumentasi, serta membuat laporan dalam bentuk PDF dan Excel.</p>
        <div class="hero-actions">
          <button class="primary-btn" onclick="showPublicComplaint()">Ajukan Pengaduan Sekarang</button>
          <button class="secondary-btn" onclick="openModal('loginModal')">Masuk Pengontrolan Sistem</button>
        </div>
        <div class="hero-trust">
          <span class="trust-chip">Tanpa login untuk pelanggan</span>
          <span class="trust-chip">Database MySQL/XAMPP</span>
          <span class="trust-chip">Upload banyak foto</span>
          <span class="trust-chip">PDF + Excel rapi</span>
        </div>
        <div class="hero-stats-wide">
          <div class="mini-stat"><b>9</b><span>Proyek perumahan</span></div>
          <div class="mini-stat"><b>Live</b><span>Data masuk ke temuan</span></div>
          <div class="mini-stat"><b>A4</b><span>Cetak dokumen rapi</span></div>
        </div>
      </div>

      <aside class="hero-panel">
        <div class="hero-panel-top">
          <div class="hero-panel-title"><small>Preview Sistem</small><b>Sistem Pengaduan SH-1</b></div>
          <div class="hero-panel-logo"><img src="assets/Ciputra.png" alt="Ciputra"></div>
        </div>
        <div class="live-card">
          <b>Alur dibuat tetap sesuai sistem Ciputra</b>
          <span>Pelanggan mengirim pengaduan → admin validasi → QC meneruskan → kontraktor mengisi jawaban → dokumen dicetak dalam format PDF atau Excel.</span>
        </div>
        <div class="mock-kqi">
          <div class="mock-row"><div class="mock-no">1</div><div><b>Pelanggan kirim foto kerusakan</b><small>Blok/unit, tanggal, nama, no HP, keterangan</small></div><span class="mock-status">Pengajuan</span></div>
          <div class="mock-row"><div class="mock-no">2</div><div><b>Admin validasi & edit data</b><small>Data masuk berdasarkan No. Laporan dan Proyek</small></div><span class="mock-status">Kontrol</span></div>
          <div class="mock-row"><div class="mock-no">3</div><div><b>Proyek konfirmasi renovasi</b><small>Penyebab, antisipasi, foto hasil perbaikan</small></div><span class="mock-status">Jawaban</span></div>
        </div>
      </aside>
    </section>

    <section class="landing-section" id="layanan">
      <div class="section-center">
        <span class="section-tag">Fitur Sistem</span>
        <h2 class="section-title-public">Satu sistem untuk pengajuan, kontrol, dan cetak laporan.</h2>
        <p class="section-text-public">Pengajuan, kontrol temuan, dokumentasi foto, dan cetak laporan PDF/Excel dibuat lebih mudah dalam satu sistem.</p>
      </div>
      <div class="feature-grid-public">
        <div class="feature-public-card"><div class="feature-icon-public"><span class="icon-min">H</span></div><h3>Pengajuan User</h3><p>Pemilik rumah cukup mengisi form di halaman khusus dan upload foto tanpa akun login.</p></div>
        <div class="feature-public-card"><div class="feature-icon-public"><span class="icon-min">T</span></div><h3>Temuan Admin</h3><p>Semua pengaduan otomatis tercatat sebagai temuan berdasarkan Proyek.</p></div>
        <div class="feature-public-card"><div class="feature-icon-public"><span class="icon-min">W</span></div><h3>Jawaban Kontraktor</h3><p>Kontraktor mengisi jawaban, jadwal perbaikan, dan foto hasil perbaikan, antisipasi, dan hasil perbaikan.</p></div>
        <div class="feature-public-card"><div class="feature-icon-public"><span class="icon-min">P</span></div><h3>Cetak Dokumen</h3><p>Admin dapat mencetak PDF dan Excel dengan bentuk dokumen yang rapi.</p></div>
      </div>
    </section>

    <section class="landing-section" id="alur">
      <div class="section-center">
        <span class="section-tag">Alur Kerja</span>
        <h2 class="section-title-public">Dari pengaduan sampai renovasi selesai.</h2>
      </div>
      <div class="steps-public">
        <div class="step-public-card"><div class="step-num-public">1</div><h3>Pelanggan Mengajukan</h3><p>Pilih proyek, isi unit, kontak, foto, dan keterangan kerusakan rumah.</p></div>
        <div class="step-public-card"><div class="step-num-public">2</div><h3>Admin Memvalidasi</h3><p>Admin melihat temuan, mengubah keterangan bila perlu, lalu meneruskan ke proyek.</p></div>
        <div class="step-public-card"><div class="step-num-public">3</div><h3>Kontraktor Menjawab</h3><p>Kontraktor menentukan jadwal, menjawab temuan, antisipasi, dan mengunggah foto hasil perbaikan.</p></div>
        <div class="step-public-card"><div class="step-num-public">4</div><h3>Dokumen Dicetak</h3><p>Temuan dan jawaban bisa dicetak sebagai dokumen PDF atau Excel yang rapi.</p></div>
      </div>
    </section>

    <footer class="public-rich-footer" id="ciputraFooter">
      <div class="footer-profile" id="footerProfileReveal">
        <img src="assets/bapak.png" alt="Dr. Ciputra">
        <div><h3>Dr. (HC) Ir. Ciputra</h3><p>Pendiri Ciputra Group, tokoh pengembang properti Indonesia yang dikenal dengan visi kewirausahaan dan pengembangan kawasan terpadu.</p></div>
      </div>
      <div class="footer-system-bottom">
        <h4><span class="icon-min">i</span> Tentang Sistem</h4>
        <p>Sistem Pengaduan Online Ciputra SH-1 berfungsi untuk mencatat, mengelola, dan memantau temuan QC serta pengaduan pelanggan selama masa garansi perbaikan 3 bulan setelah proses serah terima. Sistem ini ditampilkan dalam bentuk dashboard operasional agar proses pengecekan, tindak lanjut, dan pelaporan menjadi lebih rapi, cepat, dan terstruktur.</p>
        <div class="footer-copy">© Ciputra — Sistem Pengaduan Online SH-1</div>
      </div>
    </footer>
  </div>

  <div id="publicComplaint" class="complaint-page hide">
    <div class="complaint-page-head">
      <a class="public-brand" href="#" onclick="showPublicHome();return false"><img src="assets/Ciputra.png" alt="Ciputra"><div><small>Halaman Pengajuan</small><b>Ciputra SH-1</b></div></a>
      <div class="nav-actions"><button class="btn back-home-btn" onclick="showPublicHome()">← Kembali ke Beranda</button><button class="btn ghost" onclick="openModal('loginModal')">Login Admin / QC / Kontraktor</button></div>
    </div>
    <div class="submit-layout-new">
      <aside class="submit-info">
        <span class="section-tag">Pengajuan User</span>
        <h2>Form pengaduan pemilik rumah.</h2>
        <p>Isi data kerusakan rumah dengan lengkap. Setelah dikirim, nomor laporan dibuat otomatis dan data langsung masuk ke dashboard admin.</p>
        <div class="submit-list">
          <div><span class="check-dot">✓</span><span><b>Data aman tersimpan</b><span>Masuk ke database MySQL/XAMPP, bukan localStorage.</span></span></div>
          <div><span class="check-dot">✓</span><span><b>No. Laporan otomatis</b><span>Pengaduan pelanggan tidak memakai No. KQI.</span></span></div>
          <div><span class="check-dot">✓</span><span><b>Foto masuk ke dokumen</b><span>Foto pengaduan dipakai admin saat cetak dokumen.</span></span></div>
        </div>
      </aside>
      <main>
        <section class="public-card" id="publicFormSection">
          <div class="section-head"><div><h2>Form Pengaduan Pemilik Rumah</h2><p>Lengkapi data berikut agar admin bisa menindaklanjuti kerusakan rumah dengan tepat.</p></div></div>
          <form id="publicForm">
            <div class="form-grid">
              <div class="field full"><label>Nama Proyek</label><select name="proyek_id" id="publicProyek" required></select></div>
              <div class="field"><label>Blok / Unit Rumah</label><input name="blok_unit" required placeholder="Contoh: Blok A/12"></div>
              <div class="field"><label>Tanggal Pengaduan</label><input type="date" name="tanggal" id="publicDate" required></div>
              <div class="field"><label>Nama Pemilik / Pelapor</label><input name="nama_pelapor" required placeholder="Nama lengkap"></div>
              <div class="field"><label>No. HP yang Bisa Dihubungi</label><input name="no_hp" required inputmode="tel" placeholder="08xxxxxxxxxx"></div>
              <div class="field"><label>Email (opsional)</label><input name="email" type="email" placeholder="nama@email.com"></div>
              <div class="field"><label>Tanggal serah terima (jika ada)</label><input type="date" name="tanggal_serah_terima"></div>
              <div class="field"><label>Lokasi/area kerusakan</label><input name="area_kerusakan" placeholder="Contoh: kamar mandi, plafon, pintu utama"></div>
              <div class="field full"><label>Upload foto temuan/kerusakan</label><div class="upload" onclick="document.getElementById('publicPhotos').click()"><div><b><span class="icon-min">＋</span> Klik untuk upload foto</b><span class="muted">Bisa dari kamera/galeri dan boleh lebih dari satu foto</span></div></div><input id="publicPhotos" type="file" name="foto_temuan[]" accept="image/*" capture="environment" multiple required hidden><div class="preview" id="publicPreview"></div></div>
              <div class="field"><label>Keterangan foto</label><input name="keterangan_foto" placeholder="Contoh: retak rambut / rembesan"></div>
              <div class="field full"><label>Keterangan Temuan / Kerusakan</label><textarea name="keterangan" required placeholder="Contoh: plafon kamar bocor saat hujan, dinding retak, pipa rembes, dll."></textarea></div>
            </div>
            <div class="form-actions"><p class="trust-note">Dengan menekan konfirmasi, pengaduan akan tersimpan ke database dan menunggu validasi admin Ciputra.</p><button class="primary-btn" id="publicSubmit" type="submit">Konfirmasi Pengaduan</button></div>
          </form>
        </section>
      </main>
    </div>
  </div>
</div>

<div id="app" class="app hide">
  <aside class="sidebar" id="sidebar">
    <div class="side-brand"><img src="assets/Ciputra.png" alt="Ciputra"><div><b>Ciputra SH-1</b><span id="userLabel">Admin</span></div></div>
    <button class="nav-btn active" onclick="switchPage('dashboard', this)"><span class="icon-min">D</span> Dashboard</button>
    <button class="nav-btn admin-only" onclick="openProjects(this)"><span class="icon-min">P</span> Master Proyek</button>
    <button class="nav-btn admin-only" onclick="openAccounts(this)"><span class="icon-min">U</span> Kelola Akun</button>
    <button class="nav-btn admin-only" onclick="openAuditLogs(this)"><span class="icon-min">L</span> Audit Logs</button>
    <button class="nav-btn" onclick="openKind('qc', this)"><span class="icon-min">Q</span> Temuan QC</button>
    <button class="nav-btn" onclick="openKind('pelanggan', this)"><span class="icon-min">K</span> Temuan Pelanggan</button>
    <button class="nav-btn" onclick="openAnswers('qc', this)"><span class="icon-min">J</span> Jawaban QC</button>
    <button class="nav-btn" onclick="openAnswers('pelanggan', this)"><span class="icon-min">A</span> Jawaban Pelanggan</button>
    <button class="nav-btn" onclick="doLogout()"><span class="icon-min">↗</span> Keluar</button>
  </aside>
  <main class="main">
    <div class="topbar"><button class="btn secondary mobile-menu" onclick="toggleSidebar()">Menu</button><div><h1 id="pageTitle">Dashboard Admin</h1><p id="pageSub">Pilih jenis temuan yang akan dikelola.</p></div><button class="btn ghost" onclick="refreshCurrent()">Refresh</button></div>
    <section id="page-dashboard" class="page active">
      <div class="dashboard-hero">
        <div>
          <span class="dash-kicker">Beranda Operasional SH-1</span>
          <h2 class="dash-title">Dashboard Ciputra SH-1</h2>
          <p class="dash-lead">Pantau temuan QC dan pengaduan pelanggan/konsumen dalam satu beranda yang rapi. Data tetap mengikuti alur final: QC memakai No. KQI, sedangkan pelanggan memakai No. Dokumen/No. Laporan.</p>
          <div class="dash-actions">
            <button class="btn primary" onclick="openKind('qc')"><span class="icon-min">Q</span> Kelola Temuan QC</button>
            <button class="btn ghost" onclick="openKind('pelanggan')"><span class="icon-min">K</span> Kelola Pelanggan</button>
            <button class="btn excel" onclick="exportAllTemuanExcel()">Export Semua Dokumen</button>
          </div>
        </div>
        <div class="dash-visual">
          <div class="visual-row"><div class="visual-icon"><span class="icon-min">T</span></div><div><b>Temuan & validasi</b><small>Admin/QC dapat cek status validasi, proyek, unit, dan progres jawaban.</small></div><span class="visual-pill" id="heroTotal">0 data</span></div>
          <div class="visual-row"><div class="visual-icon"><span class="icon-min">P</span></div><div><b>Cetak PDF terpisah</b><small>PDF QC tetap KQI. PDF pelanggan tanpa KQI dan siap tanda tangan pemilik rumah.</small></div><span class="visual-pill">A4 rapi</span></div>
          <div class="visual-row"><div class="visual-icon"><span class="icon-min">X</span></div><div><b>Edit massal lewat Excel</b><small>Export, edit kolom di Excel, lalu import kembali untuk update database.</small></div><span class="visual-pill">XLSX/CSV</span></div>
        </div>
      </div>
      <div class="cards">
        <div class="stat-card"><div class="stat-label">Total Temuan</div><div class="stat-val" id="sTotal">0</div><div class="stat-sub">QC + Pelanggan</div></div>
        <div class="stat-card"><div class="stat-label">Temuan QC</div><div class="stat-val" id="sQc">0</div><div class="stat-sub">Menggunakan No. KQI</div></div>
        <div class="stat-card"><div class="stat-label">Temuan Pelanggan</div><div class="stat-val" id="sPelanggan">0</div><div class="stat-sub">No. Dokumen/Laporan</div></div>
        <div class="stat-card"><div class="stat-label">Selesai</div><div class="stat-val" id="sSelesai">0</div><div class="stat-sub"><span id="sPending">0</span> belum dijawab</div></div>
      </div>
      <div class="choice-grid">
        <div class="choice-card"><div><div class="choice-icon"><span class="icon-min">Q</span></div><h2>Temuan QC</h2><p>Untuk QC sesuai proyek. Admin hanya memonitor, kontraktor hanya menjawab. PDF QC tetap memakai KQI.</p><div class="badge b-ok" id="countQc">0 data</div></div><button class="btn primary" onclick="openKind('qc')">Masuk Temuan QC</button></div>
        <div class="choice-card"><div><div class="choice-icon"><span class="icon-min">K</span></div><h2>Temuan Pelanggan/Konsumen</h2><p>Untuk pengaduan dari pelanggan. Menggunakan Nomor/No. Dokumen/No. Laporan, tanpa No. KQI.</p><div class="badge b-process" id="countPelanggan">0 data</div></div><button class="btn primary" onclick="openKind('pelanggan')">Masuk Temuan Pelanggan</button></div>
      </div>
      <div class="charts-grid">
        <div class="chart-card"><h3>Komposisi Jenis Temuan</h3><p>Perbandingan Temuan QC dan Temuan Pelanggan/Konsumen.</p><div class="chart-box"><canvas id="chartJenis"></canvas></div></div>
        <div class="chart-card"><h3>Status Jawaban</h3><p>Monitoring data belum dijawab, proses, dan selesai.</p><div class="chart-box"><canvas id="chartStatus"></canvas></div></div>
        <div class="chart-card wide"><h3>Temuan per Proyek</h3><p>Grafik proyek seperti desain revisi lama, tetapi memakai istilah Proyek dan database final.</p><div class="chart-box"><canvas id="chartProyek"></canvas></div></div>
      </div>
      <div class="dashboard-grid-two">
        <div class="app-card"><h3 style="margin-top:0">Daftar Temuan Perlu Perhatian</h3><p class="small-muted">Menampilkan data yang belum dijawab atau masih proses.</p><div class="pending-list" id="pendingList"><div class="muted">Belum ada temuan yang perlu perhatian.</div></div></div>
        <div class="app-card excel-card"><h3 style="margin-top:0">Edit Dokumen Lewat Excel</h3><p class="small-muted">Gunakan fitur ini untuk revisi massal. Kolom <b>ID</b> jangan diubah karena dipakai untuk mencocokkan data di database.</p><div class="excel-steps"><div class="excel-step"><b>1</b><span>Export data ke Excel dari dashboard, halaman Temuan, atau halaman Jawaban.</span></div><div class="excel-step"><b>2</b><span>Edit kolom seperti tanggal, proyek_id, blok/unit, pelapor, status, penyebab, antisipasi, dan tanda tangan.</span></div><div class="excel-step"><b>3</b><span>Import kembali file Excel. Sistem akan update data sesuai ID dokumen.</span></div></div><div class="excel-actions"><button class="btn excel" onclick="exportAllTemuanExcel()">Export Semua Temuan</button><button class="btn secondary" onclick="document.getElementById('excelImportAll').click()">Import Excel Temuan</button><button class="btn ghost" onclick="exportAllJawabanExcel()">Export Semua Jawaban</button></div><input id="excelImportAll" type="file" accept=".xlsx,.xls,.csv" hidden onchange="handleExcelImport('temuan',this)"></div>
      </div>
      <div class="app-card" style="margin-top:16px"><h3 style="margin-top:0">Ringkasan per Proyek</h3><div class="table-wrap"><table><thead><tr><th>Proyek</th><th>Total</th><th>QC</th><th>Pelanggan</th><th>Selesai</th></tr></thead><tbody id="projectSummary"></tbody></table></div></div>
    </section>


    <section id="page-projects" class="page">
      <div class="toolbar"><div><h2 style="margin:0">Master Proyek</h2><p class="muted">Admin dapat menambah, mengedit, menonaktifkan, atau menghapus proyek yang belum dipakai data.</p></div><div class="filter-row"><input id="projectSearch" placeholder="Cari kode/nama/lokasi"><button class="btn secondary" onclick="loadProjects()">Filter</button><button class="btn primary" onclick="openProjectModal()">＋ Tambah Proyek</button></div></div>
      <div class="table-wrap"><table><thead><tr><th>Kode</th><th>Nama Proyek</th><th>Lokasi / Site Area</th><th>Status</th><th>Dipakai Data</th><th>Aksi</th></tr></thead><tbody id="projectsBody"></tbody></table></div>
    </section>

    <section id="page-audit" class="page">
      <div class="toolbar"><div><h2 style="margin:0">Audit Logs & Banned Access</h2><p class="muted">Pantau login sukses/gagal, hapus log, ban IP/username mencurigakan, dan buka ban jika salah blokir.</p></div><div class="filter-row"><input id="auditSearch" placeholder="Cari username/IP/action/risiko"><button class="btn secondary" onclick="loadAuditLogs()">Filter</button><button class="btn ghost" onclick="loadBannedAccess()">Refresh Banned</button></div></div>
      <div class="table-wrap"><table><thead><tr><th>Waktu</th><th>Username / Role</th><th>Status Risiko</th><th>Action / Catatan</th><th>IP & Device</th><th>Aksi</th></tr></thead><tbody id="auditBody"></tbody></table></div>
      <div class="app-card" style="margin-top:16px"><h3 style="margin-top:0">Daftar Banned IP/User</h3><p class="small-muted">Akses aktif akan ditolak sebelum proses login.</p><div class="table-wrap"><table><thead><tr><th>Tipe</th><th>Value</th><th>Alasan</th><th>Status</th><th>Dibanned oleh</th><th>Aksi</th></tr></thead><tbody id="bannedBody"></tbody></table></div></div>
    </section>

    <section id="page-accounts" class="page">
