      <div class="table-wrap"><table><thead><tr><th>Nomor</th><th>Proyek / Unit</th><th>Pelapor</th><th>Keterangan</th><th>Status</th><th>Foto</th><th>Aksi</th></tr></thead><tbody id="listBody"></tbody></table></div>
    </section>
    <section id="page-answers" class="page">
