      <div class="table-wrap"><table><thead><tr><th>Nomor</th><th>Proyek / Unit</th><th>Temuan</th><th>Status Jawaban</th><th>Tanggal Selesai</th><th>Aksi</th></tr></thead><tbody id="answersBody"></tbody></table></div>
