  </main>
</div>


<div class="modal" id="projectModal"><div class="modal-card login-modal"><div class="modal-title"><div><h2 id="projectTitle">Tambah Proyek</h2><p class="muted">Proyek aktif langsung muncul di dropdown pengajuan user dan form internal.</p></div><button class="modal-close" onclick="closeModal('projectModal')">×</button></div><form id="projectForm"><input type="hidden" name="id" id="projectId"><div class="form-grid"><div class="field full"><label>Kode Proyek</label><input name="kode_proyek" id="projectKode" placeholder="Contoh: BSD" maxlength="30" required></div><div class="field full"><label>Nama Proyek</label><input name="nama_proyek" id="projectNama" placeholder="Contoh: Ciputra BSD" required></div><div class="field full"><label>Lokasi / Site Area</label><input name="lokasi" id="projectLokasi" placeholder="Contoh: BSD / Serpong / Sentul"></div><div class="field full"><label>Status</label><select name="status" id="projectStatus"><option value="active">Aktif</option><option value="inactive">Nonaktif</option></select></div></div><div class="form-actions"><button type="button" class="btn secondary" onclick="closeModal('projectModal')">Batal</button><button class="btn primary" type="submit">Simpan Proyek</button></div></form></div></div>

<div class="modal" id="loginModal"><div class="modal-card login-modal"><div class="modal-title"><div><h2>Login Admin / QC / Kontraktor</h2><p class="muted">Masuk untuk mengelola temuan dan jawaban.</p></div><button class="modal-close" onclick="closeModal('loginModal')">×</button></div><form id="loginForm"><div class="form-grid"><div class="field full"><label>Username / Email</label><input id="loginUser" required placeholder="admin / qc / kontraktor"></div><div class="field full"><label>Password</label><input id="loginPass" type="password" required placeholder="Password"></div></div><div class="soft-note">Akun hanya dibuat oleh Admin SH-1.<br>Default: admin/admin123, qc/qc123, kontraktor/kontraktor123</div><div class="form-actions"><button class="btn primary" id="loginSubmit" type="submit">Masuk</button></div></form></div></div>
<div class="modal" id="createModal"><div class="modal-card"><div class="modal-title"><div><h2 id="createTitle">Tambah Temuan</h2><p class="muted" id="createHelp">Data tersimpan ke SQL/XAMPP.</p></div><button class="modal-close" onclick="closeModal('createModal')">×</button></div><form id="createForm"><input type="hidden" name="jenis_temuan" id="createJenis"><div class="form-grid"><div class="field" id="fieldKqi"><label>No. KQI</label><input name="nomor_kqi" placeholder="Kosongkan untuk otomatis"></div><div class="field"><label>No. Dokumen / Laporan</label><input name="nomor_dokumen" id="createNomorDok" placeholder="Otomatis jika kosong"></div><div class="field"><label>Proyek</label><select name="proyek_id" id="createProyek" required></select></div><div class="field"><label>Blok / Unit</label><input name="blok_unit" required></div><div class="field"><label>Tanggal</label><input type="date" name="tanggal" id="createDate" required></div><div class="field"><label>Nama Pelapor</label><input name="nama_pelapor" required></div><div class="field"><label>No HP</label><input name="no_hp"></div><div class="field"><label>Deadline</label><input type="date" name="deadline"></div><div class="field full"><label>Keterangan Temuan</label><textarea name="keterangan" required></textarea></div><div class="field"><label>Dampak / Komplain</label><textarea name="dampak"></textarea></div><div class="field"><label>Fakta di Lapangan</label><textarea name="fakta"></textarea></div><div class="field"><label>Penyebab Utama</label><textarea name="penyebab_utama"></textarea></div><div class="field"><label>Cara Antisipasi</label><textarea name="antisipasi"></textarea></div><div class="field"><label>Status Validasi</label><select name="status_validasi"><option value="menunggu">Menunggu</option><option value="divalidasi">Divalidasi</option><option value="ditolak">Ditolak</option></select></div><div class="field"><label>Area Kerusakan</label><input name="area_kerusakan"></div><div class="field full"><label>Keterangan foto</label><textarea name="keterangan_foto" placeholder="Satu baris per foto jika foto lebih dari satu"></textarea></div><div class="field full"><label>Upload Foto Temuan</label><div class="upload" onclick="document.getElementById('createPhotos').click()"><div><b><span class="icon-min">＋</span> Tambah foto</b><span class="muted">Bisa banyak foto</span></div></div><input id="createPhotos" type="file" name="foto_temuan[]" accept="image/*" multiple hidden><div class="preview" id="createPreview"></div></div></div><div class="form-actions"><button type="button" class="btn secondary" onclick="closeModal('createModal')">Batal</button><button class="btn primary" type="submit">Simpan Temuan</button></div></form></div></div>


<div class="modal" id="accountModal"><div class="modal-card login-modal"><div class="modal-title"><div><h2 id="accountTitle">Tambah Akun Internal</h2><p class="muted">Tidak ada register publik. Admin memilih role dan proyek akun.</p></div><button class="modal-close" onclick="closeModal('accountModal')">×</button></div><form id="accountForm"><input type="hidden" name="id" id="accountId"><div class="form-grid"><div class="field full"><label>Nama lengkap</label><input name="nama_lengkap" id="accountNama" required></div><div class="field full"><label>Username</label><input name="username" id="accountUsername" required></div><div class="field full"><label>Email</label><input name="email" id="accountEmail" type="email"></div><div class="field full"><label>No HP</label><input name="no_hp" id="accountHp"></div><div class="field"><label>Role</label><select name="role" id="accountRole"><option value="qc">QC</option><option value="kontraktor">Kontraktor</option></select></div><div class="field"><label>Proyek</label><select name="proyek_id" id="accountProyek" required></select></div><div class="field"><label>Status akun</label><select name="status" id="accountStatus"><option value="active">Aktif</option><option value="inactive">Nonaktif</option></select></div><div class="field full"><label>Password</label><input type="password" name="password" id="accountPassword" minlength="8" placeholder="Minimal 8 karakter saat tambah akun, kosongkan saat edit"></div></div><div class="form-actions"><button type="button" class="btn secondary" onclick="closeModal('accountModal')">Batal</button><button class="btn primary" type="submit">Simpan Akun</button></div></form></div></div>

<div class="modal" id="detailModal"><div class="modal-card"><div class="modal-title"><div><h2 id="detailTitle">Detail Temuan</h2><p class="muted">Edit data operasional dengan tampilan yang rapi dan aman.</p></div><button class="modal-close" onclick="closeModal('detailModal')">×</button></div><div id="detailContent"></div></div></div>
<div class="modal" id="answerModal"><div class="modal-card"><div class="modal-title"><div><h2>Jawaban / Hasil Perbaikan</h2><p class="muted">Isi penyebab, antisipasi, foto hasil perbaikan, dan tanda tangan.</p></div><button class="modal-close" onclick="closeModal('answerModal')">×</button></div><form id="answerForm"><input type="hidden" name="temuan_id" id="answerId"><div id="answerInfo" class="soft-note"></div><div class="form-grid"><div class="field"><label>Penyebab</label><textarea name="penyebab" id="answerPenyebab"></textarea></div><div class="field"><label>Antisipasi</label><textarea name="antisipasi" id="answerAntisipasi"></textarea></div><div class="field full"><label>Keterangan hasil perbaikan</label><textarea name="keterangan_perbaikan" id="answerKet"></textarea></div><div class="field"><label>Tanggal rencana perbaikan</label><input type="date" name="tanggal_rencana_perbaikan" id="answerRencanaTanggal"></div><div class="field"><label>Jam rencana perbaikan</label><input type="time" name="jam_rencana_perbaikan" id="answerRencanaJam"></div><div class="field"><label>Tanggal selesai</label><input type="date" name="tanggal_selesai" id="answerTanggal"></div><div class="field"><label>Status perbaikan</label><select name="status_perbaikan" id="answerStatus"><option value="proses">Proses</option><option value="belum_selesai">Belum Selesai</option><option value="selesai">Selesai</option></select></div><div class="field"><label>Tanda tangan admin/QC</label><input name="ttd_admin" id="ttdAdmin"></div><div class="field"><label>Tanda tangan kontraktor</label><input name="ttd_proyek" id="ttdProyek"></div><div class="field"><label>Tanda tangan pemilik rumah</label><input name="ttd_pemilik_rumah" id="ttdPemilik"></div><div class="field full"><label>Keterangan foto perbaikan</label><textarea name="keterangan_foto" placeholder="Satu baris per foto"></textarea></div><div class="field full"><label>Upload foto hasil perbaikan</label><div class="upload" onclick="document.getElementById('answerPhotos').click()"><div><b><span class="icon-min">＋</span> Pilih foto hasil perbaikan</b><span class="muted">Bisa upload lebih dari satu</span></div></div><input id="answerPhotos" type="file" name="foto_jawaban[]" accept="image/*" multiple hidden><div class="preview" id="answerPreview"></div></div></div><div class="form-actions"><button type="button" class="btn secondary" onclick="closeModal('answerModal')">Batal</button><button class="btn primary" type="submit">Simpan Jawaban</button></div></form></div></div>

<script>
const $=id=>document.getElementById(id);const csrfToken=document.querySelector('meta[name="csrf-token"]')?.content||'';let currentUser=null,currentJenis='qc',currentPage='dashboard',currentRows=[],currentAnswerRows=[],currentAnswerJenis='qc',debounceTimer=null,answerTimer=null,dashboardCharts={},allProjects=[],loaderTimer=null;
function escapeHtml(s){return String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function showLoading(text='Memproses data…'){const l=$('globalLoader');if(!l)return;l.querySelector('b').textContent=text;l.classList.remove('hide');clearTimeout(loaderTimer);loaderTimer=setTimeout(()=>hideLoading(),12000)}
function hideLoading(){const l=$('globalLoader');if(!l)return;l.classList.add('hide');clearTimeout(loaderTimer)}
function toast(title,msg='',err=false){const el=document.createElement('div');el.className='toast'+(err?' error':'');el.innerHTML=`<b>${escapeHtml(title)}</b>${msg?`<span>${escapeHtml(msg)}</span>`:''}`;document.body.appendChild(el);setTimeout(()=>el.remove(),4200)}
async function api(url,opt={}){const method=(opt.method||'GET').toUpperCase();const finalOpt={credentials:'same-origin',...opt};delete finalOpt.loadingText;if(['POST','PUT','PATCH','DELETE'].includes(method)){finalOpt.headers={...(finalOpt.headers||{}),'X-CSRF-Token':csrfToken};if(finalOpt.body instanceof FormData&&!finalOpt.body.has('_csrf_token'))finalOpt.body.append('_csrf_token',csrfToken)}showLoading(opt.loadingText||'Memproses data…');try{const res=await fetch(url,finalOpt);let data;try{data=await res.json()}catch(e){throw new Error('Respon server tidak valid.')}if(!res.ok||data.success===false)throw new Error(data.message||'Request gagal');return data}finally{hideLoading()}}
function openModal(id){$(id)?.classList.add('active')}function closeModal(id){$(id)?.classList.remove('active')}function toggleSidebar(){ $('sidebar').classList.toggle('open') }function showPublicHome(){ $('publicHome').classList.remove('hide');$('publicComplaint').classList.add('hide');window.scrollTo({top:0,behavior:'smooth'}); }function showPublicComplaint(){ $('publicHome').classList.add('hide');$('publicComplaint').classList.remove('hide');window.scrollTo({top:0,behavior:'smooth'}); }function scrollPublic(sel){ $('publicHome').classList.remove('hide');$('publicComplaint').classList.add('hide');setTimeout(()=>document.querySelector(sel)?.scrollIntoView({behavior:'smooth',block:'start'}),40); }function scrollToPublicForm(){ showPublicComplaint(); }
function today(){return new Date().toISOString().slice(0,10)}
function statusBadge(s){const map={menunggu:['Menunggu Validasi Admin','b-wait'],divalidasi:['Diterima Admin','b-ok'],ditolak:['Ditolak Admin','b-bad'],belum_dijawab:['Belum dijawab','b-wait'],proses:['Proses','b-process'],selesai:['Selesai','b-ok'],belum_selesai:['Belum selesai','b-wait'],'Menunggu Validasi Admin':['Menunggu Validasi Admin','b-wait'],'Ditolak Admin':['Ditolak Admin','b-bad'],'Diterima Admin':['Diterima Admin','b-ok'],'Diteruskan ke QC':['Diteruskan ke QC','b-process'],'Diteruskan ke Kontraktor':['Diteruskan ke Kontraktor','b-process'],'Menunggu Jadwal Perbaikan Kontraktor':['Menunggu Jadwal','b-wait'],'Jadwal Perbaikan Diajukan Kontraktor':['Jadwal Diajukan','b-process'],'Sedang Dikerjakan':['Sedang Dikerjakan','b-process'],'Selesai Dikerjakan Kontraktor':['Selesai Kontraktor','b-ok'],'Diperiksa QC':['Diperiksa QC','b-ok'],'Diteruskan ke Admin':['Diteruskan ke Admin','b-process'],'Menunggu Konfirmasi Admin ke Pelanggan':['Menunggu Konfirmasi','b-wait'],'Temuan QC Dibuat':['Temuan QC Dibuat','b-process']};const m=map[s]||[s||'-','b-process'];return `<span class="badge ${m[1]}">${escapeHtml(m[0])}</span>`}
function deadlineBadge(s){if(!s)return'';const cls=s==='Melewati Deadline'?'late':(s==='Mendekati Deadline'?'near':'normal');return `<span class="deadline-pill ${cls}">${escapeHtml(s)}</span>`}
function nomorOf(r){return r.jenis_temuan==='qc' ? (r.nomor_kqi||'-') : (r.nomor_dokumen||'-')}function jenisTitle(j){return j==='qc'?'Temuan QC':'Keluhan Pelanggan/Konsumen'}
function roleName(r){return r==='admin_sh1'?'Admin SH-1':(r==='qc'?'QC':'Kontraktor')}
async function loadProyek(){try{const data=await api('api/complaints.php?action=proyek',{loadingText:'Memuat proyek…'});allProjects=data.data||[];const opts=allProjects.map(p=>`<option value="${p.id}">${p.kode_proyek?`[${escapeHtml(p.kode_proyek)}] `:''}${escapeHtml(p.nama_proyek)}${(p.site_area||p.lokasi)?` — ${escapeHtml(p.site_area||p.lokasi)}`:''}</option>`).join('');['publicProyek','createProyek','accountProyek'].forEach(id=>{if($(id))$(id).innerHTML=opts});if($('filterProyek'))$('filterProyek').innerHTML='<option value="">Semua Proyek</option>'+opts;if($('answerFilterProyek'))$('answerFilterProyek').innerHTML='<option value="">Semua Proyek</option>'+opts}catch(e){toast('Gagal memuat proyek',e.message,true)}}
function previewFiles(input,box){const target=$(box);target.innerHTML='';[...input.files].forEach(f=>{if(!f.type.startsWith('image/'))return;const img=document.createElement('img');img.src=URL.createObjectURL(f);target.appendChild(img)})}
$('publicPhotos').addEventListener('change',e=>previewFiles(e.target,'publicPreview'));$('createPhotos').addEventListener('change',e=>previewFiles(e.target,'createPreview'));$('answerPhotos').addEventListener('change',e=>previewFiles(e.target,'answerPreview'));
$('publicForm').addEventListener('submit',async e=>{e.preventDefault();const btn=$('publicSubmit');btn.disabled=true;btn.textContent='Mengirim...';try{const fd=new FormData(e.target);const data=await api('api/complaints.php?action=create_public',{method:'POST',body:fd,loadingText:'Mengirim keluhan…'});toast('Pengaduan terkirim',`Nomor laporan: ${data.nomor_dokumen}`);e.target.reset();$('publicDate').value=today();$('publicPreview').innerHTML=''}catch(err){toast('Gagal mengirim',err.message,true)}finally{btn.disabled=false;btn.textContent='Konfirmasi Pengaduan'}});
$('loginForm').addEventListener('submit',async e=>{e.preventDefault();$('loginSubmit').disabled=true;try{const data=await api('api/auth.php?action=login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:$('loginUser').value,password:$('loginPass').value}),loadingText:'Login…'});currentUser=data.user;closeModal('loginModal');showApp();toast('Login berhasil',`Selamat datang, ${currentUser.nama_lengkap}`)}catch(err){toast('Login gagal',err.message,true)}finally{$('loginSubmit').disabled=false}});
async function checkMe(){try{const d=await api('api/auth.php?action=me',{loadingText:'Memeriksa sesi…'});if(d.user){currentUser=d.user;showApp()}else showPublic()}catch(e){showPublic()}}
function showPublic(){$('public').classList.remove('hide');$('app').classList.add('hide')}function showApp(){$('public').classList.add('hide');$('app').classList.remove('hide');$('userLabel').innerHTML=`${escapeHtml(currentUser.nama_lengkap)}<br><span class="role-pill">${roleName(currentUser.role)}${currentUser.nama_proyek?' • '+escapeHtml(currentUser.nama_proyek):''}</span>`;document.querySelectorAll('.admin-only').forEach(el=>el.style.display=currentUser.role==='admin_sh1'?'flex':'none');if(currentUser.role==='kontraktor'){openAnswers('qc')}else loadDashboard()}
async function doLogout(){try{await api('api/auth.php?action=logout',{method:'POST',loadingText:'Logout…'})}catch(e){}currentUser=null;showPublic();toast('Berhasil keluar')}
function switchPage(page,btn){currentPage=page;document.querySelectorAll('.page').forEach(p=>p.classList.remove('active'));$('page-'+page)?.classList.add('active');document.querySelectorAll('.nav-btn').forEach(b=>b.classList.remove('active'));if(btn)btn.classList.add('active');$('sidebar').classList.remove('open')}
async function loadDashboard(){switchPage('dashboard',document.querySelector('.nav-btn'));$('pageTitle').textContent='Dashboard '+roleName(currentUser.role);$('pageSub').textContent='Beranda, grafik, ringkasan proyek, status, deadline, dan tools Excel.';try{const d=await api('api/complaints.php?action=stats',{loadingText:'Memuat dashboard…'});const s=d.summary||{};$('sTotal').textContent=Number(s.total||0);$('sQc').textContent=Number(s.total_qc||0);$('sPelanggan').textContent=Number(s.total_pelanggan||0);$('sSelesai').textContent=Number(s.selesai||0);$('sPending').textContent=Number(s.belum_dijawab||0);$('heroTotal').textContent=Number(s.total||0)+' data';$('countQc').textContent=Number(s.total_qc||0)+' data';$('countPelanggan').textContent=Number(s.total_pelanggan||0)+' data';$('projectSummary').innerHTML=(d.proyek||[]).map(p=>`<tr><td><b>${escapeHtml(p.nama_proyek)}</b><br><span class="muted">${escapeHtml(p.lokasi||'')}</span></td><td>${Number(p.total||0)}</td><td>${Number(p.qc||0)}</td><td>${Number(p.pelanggan||0)}</td><td>${Number(p.selesai||0)}</td></tr>`).join('')||'<tr><td colspan="5">Belum ada data.</td></tr>';renderDashboardCharts(d);renderPendingList(d.pendingList||[])}catch(e){toast('Gagal memuat dashboard',e.message,true)}}
function renderPendingList(rows){const box=$('pendingList');box.innerHTML=(rows||[]).map((r,i)=>`<div class="pending-item"><div class="pending-no">${i+1}</div><div><b>${escapeHtml(nomorOf(r))} · ${escapeHtml(r.nama_proyek||'-')}</b><small>${escapeHtml(r.blok_unit||'-')} — ${escapeHtml(r.nama_pelapor||'-')}<br>${escapeHtml(r.keterangan||'').slice(0,120)}<br>${statusBadge(r.status)} ${deadlineBadge(r.deadline_status)}</small></div><button class="small-btn green" onclick="openDetail(${Number(r.id)})">Detail</button></div>`).join('')||'<div class="muted">Belum ada temuan yang perlu perhatian.</div>'}
function chartColors(){return ['rgba(52,211,153,.88)','rgba(56,189,248,.82)','rgba(245,158,11,.82)','rgba(248,113,113,.82)','rgba(167,139,250,.82)','rgba(236,253,245,.72)']}function makeChart(id,type,data,options={}){if(!window.Chart||!$(id))return;if(dashboardCharts[id])dashboardCharts[id].destroy();dashboardCharts[id]=new Chart($(id),{type,data,options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{labels:{color:'#ecfdf5',font:{weight:'700'}}}},scales:type==='bar'?{x:{ticks:{color:'#d1fae5'},grid:{color:'rgba(255,255,255,.08)'}},y:{beginAtZero:true,ticks:{color:'#d1fae5',precision:0},grid:{color:'rgba(255,255,255,.08)'}}}:{},...options}})}function renderDashboardCharts(d){const s=d.summary||{}, proyek=d.proyek||[], c=chartColors();makeChart('chartJenis','doughnut',{labels:['Temuan QC','Keluhan Pelanggan'],datasets:[{data:[Number(s.total_qc||0),Number(s.total_pelanggan||0)],backgroundColor:[c[0],c[1]],borderColor:'rgba(255,255,255,.12)',borderWidth:2}]});makeChart('chartStatus','doughnut',{labels:['Belum Dijawab','Proses','Selesai'],datasets:[{data:[Number(s.belum_dijawab||0),Number(s.proses||0),Number(s.selesai||0)],backgroundColor:[c[2],c[1],c[0]],borderColor:'rgba(255,255,255,.12)',borderWidth:2}]});makeChart('chartProyek','bar',{labels:proyek.map(p=>p.nama_proyek),datasets:[{label:'QC',data:proyek.map(p=>Number(p.qc||0)),backgroundColor:c[0]},{label:'Pelanggan',data:proyek.map(p=>Number(p.pelanggan||0)),backgroundColor:c[1]},{label:'Selesai',data:proyek.map(p=>Number(p.selesai||0)),backgroundColor:c[2]}]},{plugins:{legend:{position:'bottom',labels:{color:'#ecfdf5',font:{weight:'700'}}}}})}
function openKind(j,btn){currentJenis=j;switchPage('list',btn);$('pageTitle').textContent=jenisTitle(j);$('pageSub').textContent=j==='qc'?'QC membuat temuan untuk proyeknya dan meneruskan ke kontraktor.':'Pelanggan mengirim keluhan publik; Admin validasi dan teruskan ke QC.';loadList()}
function rowActions(r){let a=`<button class="small-btn green" onclick="openDetail(${r.id})">Detail</button><button class="small-btn white" onclick="printOne('temuan',${r.id},'${r.jenis_temuan}')">PDF</button><button class="small-btn white" onclick="excelOne('temuan',${r.id},'${r.jenis_temuan}')">Excel</button>`;if(currentUser.role==='kontraktor')a+=`<button class="small-btn" onclick="openAnswer(${r.id})">Isi Jawaban</button>`;if(currentUser.role==='admin_sh1')a+=`<button class="small-btn red" onclick="deleteRow(${r.id})">Hapus</button>`;return a}
async function loadList(){try{const q=new URLSearchParams({action:'list',jenis:currentJenis,proyek_id:$('filterProyek').value,status_jawaban:$('filterJawaban').value,search:$('searchBox').value});const d=await api('api/complaints.php?'+q,{loadingText:'Memuat data…'});currentRows=d.data||[];$('listBody').innerHTML=currentRows.map(r=>`<tr><td><b>${escapeHtml(nomorOf(r))}</b><br><span class="muted">${r.jenis_temuan==='qc'?'QC':'Pelanggan'}</span></td><td>${escapeHtml(r.nama_proyek)}<br><span class="muted">${escapeHtml(r.blok_unit)}</span></td><td>${escapeHtml(r.nama_pelapor)}<br><span class="muted">${escapeHtml(r.no_hp||'-')}</span></td><td>${escapeHtml(r.keterangan).slice(0,130)}<br>${r.qc_name?`<span class="muted">QC: ${escapeHtml(r.qc_name)}</span><br>`:''}${r.kontraktor_name?`<span class="muted">Kontraktor: ${escapeHtml(r.kontraktor_name)}</span>`:''}</td><td>${statusBadge(r.status||r.status_validasi)}<br>${statusBadge(r.status_jawaban)}<br>${deadlineBadge(r.deadline_status)}</td><td>${Number(r.foto_count||0)} foto</td><td><div class="row-actions">${rowActions(r)}</div></td></tr>`).join('')||'<tr><td colspan="7">Belum ada data.</td></tr>'}catch(e){toast('Gagal memuat data',e.message,true)}}
function debouncedLoad(){clearTimeout(debounceTimer);debounceTimer=setTimeout(loadList,350)}function openAnswers(j,btn){currentAnswerJenis=j;switchPage('answers',btn);$('pageTitle').textContent='Jawaban '+(j==='qc'?'QC':'Pelanggan/Konsumen');$('pageSub').textContent='Kontraktor mengisi jawaban, jadwal perbaikan, dan foto hasil perbaikan.';loadAnswers()}
async function loadAnswers(){try{const q=new URLSearchParams({action:'list',jenis:currentAnswerJenis,proyek_id:$('answerFilterProyek').value,search:$('answerSearch').value});const d=await api('api/complaints.php?'+q,{loadingText:'Memuat jawaban…'});currentAnswerRows=d.data||[];$('answersBody').innerHTML=currentAnswerRows.map(r=>`<tr><td><b>${escapeHtml(nomorOf(r))}</b><br>${statusBadge(r.status||'')}</td><td>${escapeHtml(r.nama_proyek)}<br><span class="muted">${escapeHtml(r.blok_unit)}</span></td><td>${escapeHtml(r.keterangan).slice(0,150)}<br>${deadlineBadge(r.deadline_status)}</td><td>${statusBadge(r.status_jawaban)}<br><span class="muted">${Number(r.foto_jawaban_count||0)} foto hasil</span></td><td>${escapeHtml(r.tanggal_selesai||'-')}</td><td><div class="row-actions">${currentUser.role==='kontraktor'?`<button class="small-btn green" onclick="openAnswer(${r.id})">Isi/Edit</button>`:''}<button class="small-btn" onclick="openDetail(${r.id})">Detail</button><button class="small-btn white" onclick="printOne('jawaban',${r.id},'${r.jenis_temuan}')">PDF</button><button class="small-btn white" onclick="excelOne('jawaban',${r.id},'${r.jenis_temuan}')">Excel</button></div></td></tr>`).join('')||'<tr><td colspan="6">Belum ada data.</td></tr>'}catch(e){toast('Gagal memuat jawaban',e.message,true)}}
function debouncedAnswers(){clearTimeout(answerTimer);answerTimer=setTimeout(loadAnswers,350)}
function openCreateModal(){if(currentUser.role!=='qc'){toast('Akses ditolak','Temuan manual hanya boleh dibuat oleh QC sesuai proyeknya.',true);return}const j=currentJenis;if(j!=='qc'){toast('Tidak boleh','Keluhan pelanggan hanya dari form publik dan validasi Admin.',true);return}$('createForm').reset();$('createJenis').value='qc';$('createDate').value=today();$('createPreview').innerHTML='';$('fieldKqi').style.display='grid';$('createTitle').textContent='Tambah Temuan QC';$('createHelp').textContent='Temuan QC otomatis terikat proyek QC. Kosongkan No. KQI untuk nomor otomatis.';if(currentUser.proyek_id)$('createProyek').value=currentUser.proyek_id;openModal('createModal')}
$('createForm').addEventListener('submit',async e=>{e.preventDefault();try{const fd=new FormData(e.target);const d=await api('api/complaints.php?action=create',{method:'POST',body:fd,loadingText:'Menyimpan temuan QC…'});toast('Temuan tersimpan',d.nomor_kqi||'');closeModal('createModal');loadList();loadDashboard()}catch(err){toast('Gagal menyimpan',err.message,true)}});
async function assigneeId(role,proyekId){const d=await api(`api/complaints.php?action=assignees&role=${role}&proyek_id=${proyekId}`,{loadingText:'Memuat akun…'});const rows=d.data||[];if(!rows.length){toast('Akun belum ada',`Buat akun ${role} untuk proyek ini terlebih dahulu.`,true);return 0}const text=rows.map(x=>`${x.id}: ${x.nama_lengkap} (${x.username})`).join('\n');const val=prompt(`Pilih ID ${role.toUpperCase()} untuk proyek ini:\n${text}`);return Number(val||0)}
async function workflow(id,op,extra={}){try{await api('api/complaints.php?action=workflow',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,op,...extra}),loadingText:'Memperbarui alur…'});toast('Alur diperbarui');closeModal('detailModal');refreshCurrent();loadDashboard()}catch(e){toast('Gagal update alur',e.message,true)}}
async function forwardToQc(id,proyekId){const qc_id=await assigneeId('qc',proyekId);if(qc_id)workflow(id,'forward_to_qc',{qc_id})}async function forwardToContractor(id,proyekId){const kontraktor_id=await assigneeId('kontraktor',proyekId);if(kontraktor_id)workflow(id,'forward_to_contractor',{kontraktor_id})}function rejectCustomer(id){const alasan=prompt('Alasan penolakan:','Masa garansi/persyaratan belum terpenuhi.');if(alasan!==null)workflow(id,'reject_customer',{alasan_penolakan:alasan})}
function workflowButtons(r){let out='';if(currentUser.role==='admin_sh1'&&r.jenis_temuan==='pelanggan'&&(r.status==='Menunggu Validasi Admin'||r.status==='Diterima Admin'))out+=`<button class="btn primary" onclick="forwardToQc(${r.id},${r.proyek_id})">Teruskan ke QC</button><button class="btn danger" onclick="rejectCustomer(${r.id})">Tolak Keluhan</button>`;if(currentUser.role==='qc'&&(r.status==='Diteruskan ke QC'||r.status==='Temuan QC Dibuat'||r.status==='Diterima Admin'))out+=`<button class="btn primary" onclick="forwardToContractor(${r.id},${r.proyek_id})">Teruskan ke Kontraktor</button>`;if(currentUser.role==='qc'&&r.status==='Selesai Dikerjakan Kontraktor')out+=`<button class="btn primary" onclick="workflow(${r.id},'qc_approve')">Setujui Hasil Kontraktor</button>`;if(currentUser.role==='admin_sh1'&&r.status==='Menunggu Konfirmasi Admin ke Pelanggan')out+=`<button class="btn primary" onclick="workflow(${r.id},'admin_confirm_done')">Konfirmasi Selesai ke Pelanggan</button>`;return out}
async function openDetail(id){try{const d=await api('api/complaints.php?action=detail&id='+id,{loadingText:'Membuka detail…'});const r=d.data;const photos=d.photos||[];$('detailTitle').textContent=`Detail ${r.jenis_temuan==='qc'?'Temuan QC':'Keluhan Pelanggan'}`;const canEdit=(currentUser.role==='qc'&&r.jenis_temuan==='qc')||(currentUser.role==='admin_sh1'&&r.jenis_temuan==='pelanggan'&&(r.status==='Menunggu Validasi Admin'||r.status==='Diterima Admin'));const noLabel=r.jenis_temuan==='qc'?'No. KQI':'No. Dokumen / Laporan';$('detailContent').innerHTML=`<div class="detail-grid"><div class="detail-box"><h3>Data Temuan</h3><div class="soft-note"><b>Status:</b> ${statusBadge(r.status)} ${deadlineBadge(r.deadline_status)}<br><b>QC:</b> ${escapeHtml(r.qc_name||'-')} · <b>Kontraktor:</b> ${escapeHtml(r.kontraktor_name||'-')}</div><form id="editForm"><input type="hidden" name="id" value="${r.id}"><div class="form-grid"><div class="field"><label>${noLabel}</label><input name="${r.jenis_temuan==='qc'?'nomor_kqi':'nomor_dokumen'}" value="${escapeHtml(nomorOf(r))}" ${!canEdit?'readonly':''}></div>${r.jenis_temuan==='qc'?`<div class="field"><label>No. Dokumen</label><input name="nomor_dokumen" value="${escapeHtml(r.nomor_dokumen||'')}" ${!canEdit?'readonly':''}></div>`:''}<div class="field"><label>Proyek</label><select name="proyek_id" id="editProyek" ${!canEdit?'disabled':''}></select></div><div class="field"><label>Blok / Unit</label><input name="blok_unit" value="${escapeHtml(r.blok_unit)}" ${!canEdit?'readonly':''}></div><div class="field"><label>Tanggal</label><input type="date" name="tanggal" value="${escapeHtml(r.tanggal)}" ${!canEdit?'readonly':''}></div><div class="field"><label>Nama Pelapor</label><input name="nama_pelapor" value="${escapeHtml(r.nama_pelapor)}" ${!canEdit?'readonly':''}></div><div class="field"><label>No HP</label><input name="no_hp" value="${escapeHtml(r.no_hp||'')}" ${!canEdit?'readonly':''}></div><div class="field"><label>Deadline</label><input type="date" name="deadline" value="${escapeHtml(r.deadline||r.tanggal_deadline_kontraktor||'')}" ${!canEdit?'readonly':''}></div><div class="field full"><label>Keterangan</label><textarea name="keterangan" ${!canEdit?'readonly':''}>${escapeHtml(r.keterangan)}</textarea></div><div class="field"><label>Status Validasi</label><select name="status_validasi" ${!canEdit?'disabled':''}><option value="menunggu">Menunggu</option><option value="divalidasi">Divalidasi</option><option value="ditolak">Ditolak</option></select></div><div class="field"><label>Status Jawaban</label><select name="status_jawaban" ${!canEdit?'disabled':''}><option value="belum_dijawab">Belum Dijawab</option><option value="proses">Proses</option><option value="selesai">Selesai</option></select></div></div><div class="form-actions">${workflowButtons(r)}<button type="button" class="btn secondary" onclick="printOne('temuan',${r.id},'${r.jenis_temuan}')">Cetak PDF</button><button type="button" class="btn ghost" onclick="excelOne('temuan',${r.id},'${r.jenis_temuan}')">Cetak Excel</button>${canEdit?'<button class="btn primary" type="submit">Simpan Edit</button>':''}</div></form></div><div class="detail-box"><h3>Foto Temuan</h3><div class="photo-list">${photos.map(p=>`<div><img src="${escapeHtml(p.foto_path)}"><span class="muted">${escapeHtml(p.keterangan_foto||'Foto')}</span></div>`).join('')||'<span class="muted">Belum ada foto.</span>'}</div><h3 style="margin-top:18px">Jawaban Kontraktor</h3><div class="detail-line"><b>Status</b><span>${statusBadge(r.status_jawaban)}</span></div>${currentUser.role==='kontraktor'?`<div class="form-actions"><button class="btn primary" onclick="openAnswer(${r.id})">Isi/Edit Jawaban</button></div>`:''}</div></div>`;fillSelect('editProyek',r.proyek_id);document.querySelector('#editForm [name=status_validasi]').value=r.status_validasi;document.querySelector('#editForm [name=status_jawaban]').value=r.status_jawaban;if(canEdit)document.getElementById('editForm').addEventListener('submit',saveEdit);openModal('detailModal')}catch(e){toast('Gagal membuka detail',e.message,true)}}
function fillSelect(id,selected){$(id).innerHTML=$('createProyek').innerHTML;$(id).value=selected}async function saveEdit(e){e.preventDefault();const fd=new FormData(e.target);const obj=Object.fromEntries(fd.entries());try{await api('api/complaints.php?action=update',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(obj),loadingText:'Menyimpan edit…'});toast('Data diperbarui');closeModal('detailModal');loadList();loadAnswers();loadDashboard()}catch(err){toast('Gagal update',err.message,true)}}
async function openAnswer(id){if(currentUser.role!=='kontraktor'){toast('Akses ditolak','Jawaban hanya boleh diisi Kontraktor.',true);return}try{const d=await api('api/complaints.php?action=detail&id='+id,{loadingText:'Membuka jawaban…'});const r=d.data,j=d.jawaban||{};$('answerForm').reset();$('answerPreview').innerHTML='';$('answerId').value=id;$('answerInfo').innerHTML=`<b>${escapeHtml(nomorOf(r))}</b><br>${escapeHtml(r.nama_proyek)} — ${escapeHtml(r.blok_unit)}<br>${escapeHtml(r.keterangan)}<br>${deadlineBadge(r.deadline_status)}`;$('answerPenyebab').value=j.penyebab||r.penyebab_utama||'';$('answerAntisipasi').value=j.antisipasi||r.antisipasi||'';$('answerKet').value=j.keterangan_perbaikan||j.jawaban_kontraktor||'';if($('answerRencanaTanggal'))$('answerRencanaTanggal').value=j.tanggal_rencana_perbaikan||'';if($('answerRencanaJam'))$('answerRencanaJam').value=(j.jam_rencana_perbaikan||'').slice(0,5);$('answerTanggal').value=j.tanggal_selesai||today();$('answerStatus').value=j.status_perbaikan||'proses';$('ttdAdmin').value=j.ttd_admin||'';$('ttdProyek').value=j.ttd_proyek||currentUser.nama_lengkap||'';$('ttdPemilik').value=j.ttd_pemilik_rumah||'';openModal('answerModal')}catch(e){toast('Gagal membuka jawaban',e.message,true)}}
$('answerForm').addEventListener('submit',async e=>{e.preventDefault();try{const fd=new FormData(e.target);await api('api/complaints.php?action=save_answer',{method:'POST',body:fd,loadingText:'Menyimpan jawaban…'});toast('Jawaban tersimpan');closeModal('answerModal');loadList();loadAnswers();loadDashboard()}catch(err){toast('Gagal menyimpan jawaban',err.message,true)}});
async function openAccounts(btn){if(currentUser.role!=='admin_sh1'){toast('Akses ditolak','Hanya Admin SH-1 yang bisa mengelola akun.',true);return}switchPage('accounts',btn);$('pageTitle').textContent='Kelola Akun QC & Kontraktor';$('pageSub').textContent='Akun internal dibuat admin dan wajib terikat proyek.';loadAccounts()}
async function loadAccounts(){try{const d=await api('api/users.php?action=list',{loadingText:'Memuat akun…'});const rows=d.data||[];$('accountsBody').innerHTML=rows.map(u=>`<tr><td><b>${escapeHtml(u.nama_lengkap)}</b><br><span class="muted">${escapeHtml(u.username)}</span></td><td><span class="role-pill">${roleName(u.role)}</span></td><td>${escapeHtml(u.nama_proyek||'-')}</td><td>${escapeHtml(u.email||'-')}<br><span class="muted">${escapeHtml(u.no_hp||'-')}</span></td><td>${u.status==='active'?statusBadge('selesai'):statusBadge('ditolak')}</td><td><div class="row-actions"><button class="small-btn green" onclick='openAccountModal(${JSON.stringify(u)})'>Edit</button><button class="small-btn" onclick="resetAccountPassword(${u.id})">Reset Password</button></div></td></tr>`).join('')||'<tr><td colspan="6">Belum ada akun QC/Kontraktor.</td></tr>'}catch(e){toast('Gagal memuat akun',e.message,true)}}
function openAccountModal(u=null){$('accountForm').reset();$('accountId').value=u?.id||'';$('accountTitle').textContent=u?'Edit Akun Internal':'Tambah Akun Internal';$('accountNama').value=u?.nama_lengkap||'';$('accountUsername').value=u?.username||'';$('accountEmail').value=u?.email||'';$('accountHp').value=u?.no_hp||'';$('accountRole').value=u?.role||'qc';$('accountProyek').value=u?.proyek_id||($('accountProyek').value||'');$('accountStatus').value=u?.status||'active';$('accountPassword').required=!u;openModal('accountModal')}
$('accountForm').addEventListener('submit',async e=>{e.preventDefault();const obj=Object.fromEntries(new FormData(e.target).entries());const action=obj.id?'update':'create';if(action==='update'&&!obj.password)delete obj.password;try{await api('api/users.php?action='+action,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(obj),loadingText:'Menyimpan akun…'});toast('Akun tersimpan');closeModal('accountModal');loadAccounts()}catch(err){toast('Gagal menyimpan akun',err.message,true)}});
async function resetAccountPassword(id){const password=prompt('Masukkan password baru minimal 8 karakter:');if(!password)return;try{await api('api/users.php?action=reset_password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,password}),loadingText:'Reset password…'});toast('Password direset')}catch(e){toast('Gagal reset password',e.message,true)}}

async function openProjects(btn){if(currentUser.role!=='admin_sh1'){toast('Akses ditolak','Hanya Admin SH-1 yang bisa mengelola proyek.',true);return}switchPage('projects',btn);$('pageTitle').textContent='Master Proyek';$('pageSub').textContent='Tambah proyek baru tanpa edit kode manual. Proyek aktif otomatis muncul di form pengajuan.';loadProjects()}
async function loadProjects(){try{const q=new URLSearchParams({action:'list',search:$('projectSearch')?.value||''});const d=await api('api/projects.php?'+q,{loadingText:'Memuat proyek…'});const rows=d.data||[];$('projectsBody').innerHTML=rows.map(p=>`<tr><td><span class="project-code">${escapeHtml(p.kode_proyek||'-')}</span></td><td><b>${escapeHtml(p.nama_proyek)}</b></td><td>${escapeHtml(p.site_area||p.lokasi||'-')}</td><td>${p.status==='active'?statusBadge('selesai'):statusBadge('ditolak')}</td><td>${Number(p.used_count||0)} data</td><td><div class="row-actions"><button class="small-btn green" onclick='openProjectModal(${JSON.stringify(p)})'>Edit</button><button class="small-btn" onclick="toggleProject(${Number(p.id)},'${p.status==='active'?'inactive':'active'}')">${p.status==='active'?'Nonaktifkan':'Aktifkan'}</button><button class="small-btn red" onclick="deleteProject(${Number(p.id)})">Hapus</button></div></td></tr>`).join('')||'<tr><td colspan="6">Belum ada proyek.</td></tr>'}catch(e){toast('Gagal memuat proyek',e.message,true)}}
function openProjectModal(p=null){$('projectForm').reset();$('projectId').value=p?.id||'';$('projectTitle').textContent=p?'Edit Proyek':'Tambah Proyek';$('projectKode').value=p?.kode_proyek||'';$('projectNama').value=p?.nama_proyek||'';$('projectLokasi').value=p?.site_area||p?.lokasi||'';$('projectStatus').value=p?.status||'active';openModal('projectModal')}
$('projectForm').addEventListener('submit',async e=>{e.preventDefault();const obj=Object.fromEntries(new FormData(e.target).entries());const action=obj.id?'update':'create';try{await api('api/projects.php?action='+action,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(obj),loadingText:'Menyimpan proyek…'});toast('Proyek tersimpan');closeModal('projectModal');await loadProyek();loadProjects();loadDashboard()}catch(err){toast('Gagal menyimpan proyek',err.message,true)}});
async function toggleProject(id,status){try{await api('api/projects.php?action=toggle',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,status}),loadingText:'Mengubah status proyek…'});toast('Status proyek diperbarui');await loadProyek();loadProjects()}catch(e){toast('Gagal mengubah proyek',e.message,true)}}
async function deleteProject(id){if(!confirm('Hapus proyek ini? Jika sudah dipakai data, sistem akan menonaktifkan agar data lama tetap aman.'))return;try{const d=await api('api/projects.php?action=delete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id}),loadingText:'Menghapus proyek…'});toast('Proyek diproses',d.message||'Selesai.');await loadProyek();loadProjects();loadDashboard()}catch(e){toast('Gagal hapus proyek',e.message,true)}}
function riskBadge(r){const v=(r||'normal').toLowerCase();return `<span class="risk-pill risk-${escapeHtml(v)}">${escapeHtml(r||'normal')}</span>`}
async function deleteAuditLog(id){if(!confirm('Hapus audit log ini?'))return;try{await api('api/logs.php?action=delete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id}),loadingText:'Menghapus log…'});toast('Audit log dihapus');loadAuditLogs()}catch(e){toast('Gagal hapus log',e.message,true)}}
async function banAccess(type,value){if(!value){toast('Data kosong','Tidak ada value untuk dibanned.',true);return}const reason=prompt(`Alasan ban ${type} ${value}:`,'Aktivitas login mencurigakan');if(reason===null)return;try{await api('api/logs.php?action=ban',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ban_type:type,ban_value:value,reason}),loadingText:'Memproses ban…'});toast('Ban aktif',`${type}: ${value}`);loadBannedAccess()}catch(e){toast('Gagal ban akses',e.message,true)}}
async function unbanAccess(id){try{await api('api/logs.php?action=unban',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id}),loadingText:'Membuka ban…'});toast('Ban dibuka');loadBannedAccess()}catch(e){toast('Gagal unban',e.message,true)}}
async function loadBannedAccess(){try{const d=await api('api/logs.php?action=banned_list',{loadingText:'Memuat banned access…'});const rows=d.data||[];$('bannedBody').innerHTML=rows.map(b=>`<tr><td>${escapeHtml(b.ban_type)}</td><td><b>${escapeHtml(b.ban_value)}</b></td><td>${escapeHtml(b.reason||'-')}</td><td>${b.status==='active'?riskBadge('blocked'):statusBadge('ditolak')}</td><td>${escapeHtml(b.banned_by_name||'-')}</td><td>${b.status==='active'?`<button class="small-btn green" onclick="unbanAccess(${Number(b.id)})">Unban</button>`:'<span class="muted">Inactive</span>'}</td></tr>`).join('')||'<tr><td colspan="6">Belum ada banned IP/user.</td></tr>'}catch(e){toast('Gagal memuat banned access',e.message,true)}}

function excelText(v){return v==null?'':String(v)}function temuanExcelRows(rows){return (rows||[]).map(r=>({ID:r.id,jenis_temuan:r.jenis_temuan,status:r.status||'',deadline_status:r.deadline_status||'',nomor_kqi:r.nomor_kqi||'',nomor_dokumen:r.nomor_dokumen||'',proyek_id:r.proyek_id||'',nama_proyek:r.nama_proyek||'',blok_unit:r.blok_unit||'',tanggal:r.tanggal||'',nama_pelapor:r.nama_pelapor||'',no_hp:r.no_hp||'',email:r.email||'',keterangan:r.keterangan||'',deadline:r.deadline||r.tanggal_deadline_kontraktor||'',status_validasi:r.status_validasi||'',status_jawaban:r.status_jawaban||'',qc:r.qc_name||'',kontraktor:r.kontraktor_name||''}))}function jawabanExcelRows(rows){return (rows||[]).map(r=>({ID:r.id,jenis_temuan:r.jenis_temuan,nomor:nomorOf(r),proyek_id:r.proyek_id||'',nama_proyek:r.nama_proyek||'',blok_unit:r.blok_unit||'',nama_pelapor:r.nama_pelapor||'',no_hp:r.no_hp||'',keterangan_temuan:r.keterangan||'',penyebab:r.jawaban_penyebab||'',antisipasi:r.jawaban_antisipasi||'',keterangan_perbaikan:r.keterangan_perbaikan||'',tanggal_selesai:r.tanggal_selesai||'',status_perbaikan:r.status_perbaikan||'',ttd_admin:r.ttd_admin||'',ttd_kontraktor:r.ttd_proyek||'',ttd_pemilik_rumah:r.ttd_pemilik_rumah||''}))}
function downloadExcel(rows,filename,sheet='Data'){if(!window.XLSX){toast('Library Excel belum termuat','Periksa koneksi internet untuk CDN SheetJS.',true);return}const ws=XLSX.utils.json_to_sheet(rows);const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,sheet);const widths=Object.keys(rows[0]||{ID:''}).map(k=>({wch:Math.min(Math.max(k.length+4,14),38)}));ws['!cols']=widths;XLSX.writeFile(wb,filename)}function exportCurrentTemuanExcel(){if(!currentRows.length){toast('Data kosong','Tidak ada data pada filter aktif.',true);return}downloadExcel(temuanExcelRows(currentRows),`ciputra-sh-temuan-${currentJenis}-${today()}.xlsx`,'Temuan')}function exportCurrentJawabanExcel(){if(!currentAnswerRows.length){toast('Data kosong','Tidak ada jawaban pada filter aktif.',true);return}downloadExcel(jawabanExcelRows(currentAnswerRows),`ciputra-sh-jawaban-${currentAnswerJenis}-${today()}.xlsx`,'Jawaban')}async function exportAllTemuanExcel(){try{const d=await api('api/complaints.php?action=list',{loadingText:'Export data…'});const rows=d.data||[];if(!rows.length){toast('Data kosong','Belum ada temuan untuk diexport.',true);return}downloadExcel(temuanExcelRows(rows),`ciputra-sh-semua-temuan-${today()}.xlsx`,'Semua Temuan')}catch(e){toast('Gagal export Excel',e.message,true)}}async function exportAllJawabanExcel(){try{const d=await api('api/complaints.php?action=list',{loadingText:'Export jawaban…'});const rows=d.data||[];if(!rows.length){toast('Data kosong','Belum ada jawaban untuk diexport.',true);return}downloadExcel(jawabanExcelRows(rows),`ciputra-sh-semua-jawaban-${today()}.xlsx`,'Semua Jawaban')}catch(e){toast('Gagal export Excel',e.message,true)}}
function normalizeExcelRow(row){const out={};Object.entries(row||{}).forEach(([k,v])=>{const key=String(k).trim().toLowerCase().replace(/\s+/g,'_');out[key]=v==null?'':v});return out}function readExcelFile(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=e=>{try{const wb=XLSX.read(new Uint8Array(e.target.result),{type:'array'});const ws=wb.Sheets[wb.SheetNames[0]];resolve(XLSX.utils.sheet_to_json(ws,{defval:''}).map(normalizeExcelRow))}catch(err){reject(err)}};reader.onerror=()=>reject(new Error('File tidak bisa dibaca.'));reader.readAsArrayBuffer(file)})}async function handleExcelImport(mode,input){const file=input.files&&input.files[0];if(!file)return;if(!window.XLSX){toast('Library Excel belum termuat','Periksa koneksi internet untuk CDN SheetJS.',true);input.value='';return}try{const rows=await readExcelFile(file);if(!rows.length){toast('Excel kosong','Tidak ada baris data yang terbaca.',true);return}if(!confirm(`Import ${rows.length} baris Excel untuk update ${mode==='jawaban'?'jawaban/perbaikan':'temuan'}? Pastikan kolom ID tidak diubah.`))return;const res=await api('api/complaints.php?action=bulk_update',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mode,rows}),loadingText:'Import Excel…'});toast('Import Excel berhasil',`${res.updated||0} data diperbarui${res.skipped?`, ${res.skipped} dilewati`:''}.`);refreshCurrent();loadDashboard()}catch(e){toast('Gagal import Excel',e.message,true)}finally{input.value=''}}async function deleteRow(id){if(!confirm('Hapus data temuan ini?'))return;try{await api('api/complaints.php?action=delete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id}),loadingText:'Menghapus…'});toast('Data dihapus');loadList();loadDashboard()}catch(e){toast('Gagal menghapus',e.message,true)}}
async function openAuditLogs(btn){if(currentUser.role!=='admin_sh1'){toast('Akses ditolak','Hanya Admin SH-1 yang bisa melihat audit logs.',true);return}switchPage('audit',btn);$('pageTitle').textContent='Audit Logs & Banned Access';$('pageSub').textContent='Keamanan login: hapus log, ban IP/user, dan unban jika diperlukan.';loadAuditLogs();loadBannedAccess()}async function loadAuditLogs(){try{const q=new URLSearchParams({action:'list',search:$('auditSearch')?.value||'',limit:'50'});const d=await api('api/logs.php?'+q,{loadingText:'Memuat audit logs…'});const rows=d.data||[];$('auditBody').innerHTML=rows.map(l=>{const username=l.username_attempt||('User #'+(l.user_id||'-'));const role=l.role_attempt||l.role||'-';const risk=l.risk_level||((String(l.action||'').includes('gagal'))?'mencurigakan':'normal');const userValue=l.username_attempt||l.user_id||'';return `<tr><td>${escapeHtml(l.created_at||'-')}</td><td><b>${escapeHtml(username)}</b><br><span class="muted">${escapeHtml(role)}</span></td><td>${escapeHtml(l.status||'-')}<br>${riskBadge(risk)}<br><span class="muted">Gagal: ${Number(l.failed_attempts||0)}x</span></td><td>${escapeHtml(l.action||'-')}<br><span class="muted">${escapeHtml(l.notes||((l.table_name||'-')+' #'+(l.record_id||'-')))}</span></td><td>${escapeHtml(l.ip_address||'-')}<br><span class="muted">${escapeHtml(l.user_agent||'-').slice(0,70)}</span></td><td><div class="row-actions"><button class="small-btn red" onclick="deleteAuditLog(${Number(l.id)})">Hapus</button><button class="small-btn" onclick="banAccess('ip','${escapeHtml(l.ip_address||'')}')">Ban IP</button><button class="small-btn" onclick="banAccess('user','${escapeHtml(String(userValue)).replace(/'/g,'&#39;')}')">Ban User</button></div></td></tr>`}).join('')||'<tr><td colspan="6">Belum ada log.</td></tr>'}catch(e){toast('Gagal memuat log',e.message,true)}}function printOne(mode,id,jenis){window.open(`print.php?mode=${encodeURIComponent(mode)}&jenis=${encodeURIComponent(jenis)}&ids=${id}`,'_blank')}function printAllAnswers(){window.open(`print.php?mode=jawaban&jenis=${encodeURIComponent(currentAnswerJenis)}`,'_blank')}function excelOne(mode,id,jenis){window.location.href=`excel.php?mode=${encodeURIComponent(mode)}&jenis=${encodeURIComponent(jenis)}&ids=${id}`}function excelAllAnswers(){window.location.href=`excel.php?mode=jawaban&jenis=${encodeURIComponent(currentAnswerJenis)}`}function refreshCurrent(){if(currentPage==='dashboard')loadDashboard();else if(currentPage==='list')loadList();else if(currentPage==='answers')loadAnswers();else if(currentPage==='accounts')loadAccounts();else if(currentPage==='projects')loadProjects();else if(currentPage==='audit'){loadAuditLogs();loadBannedAccess()}}window.addEventListener('click',e=>{if(e.target.classList.contains('modal'))e.target.classList.remove('active')});
function initFooterReveal(){const el=$('footerProfileReveal');if(!el)return;if(!('IntersectionObserver' in window)){el.classList.add('reveal');return}const obs=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){el.classList.add('reveal');obs.disconnect()}})},{threshold:.32});obs.observe(el)}
(async function init(){try{initFooterReveal();$('publicDate').value=today();$('createDate').value=today();await loadProyek();await checkMe()}finally{hideLoading()}})();
</script>
</body>
</html>
